STOPS={'TAA','TAG','TGA'}
STARTS={'ATG','GTG','TTG'}

def scan_ORFs(s, min_len):
    """returns list of (prot_len, start_nt(1-based on s), stop_nt(1-based) ) for ORFs in this sequence, scanning every ATG/GTG/TTG and reading to first stop"""
    res=[]
    for fr in range(3):
        i=fr
        while i+2 < len(s):
            c=s[i:i+3]
            if c in STARTS and c=='ATG':
                # read to stop
                j=i
                prot=[]
                while j+2 < len(s):
                    c3=s[j:j+3]
                    if c3 in STOPS:
                        break
                    prot.append(c3)
                    j+=3
                aalen=(j-i)//3
                if j+2 < len(s) and aalen>=min_len:   # found a stop -> closed ORF
                    res.append((aalen, i+1, j+3, ''.join(tbl[c] for c in prot)))
                i+=3
            else:
                i+=3
    return res

# codon table
