def rc(s): return s[::-1].translate(str.maketrans('ACGT','TGCA'))
STOPS={'TAA','TAG','TGA'}
STARTS={'ATG'} 
def all_orfs(s,minaa):
    out=[]
    for fr in range(3):
        # find stop positions in frame
        stops=[i for i in range(fr,len(s)-2,3) if s[i:i+3] in STOPS]
        if not stops: continue
        prev=-3  # previous stop pos (0-based)
        for st in stops:
            # ORF between prev+3 and st
            seg_start=prev+3
            if st-seg_start>=3*minaa:
                # count starts (ATG) in [seg_start, st-3]
                starts=[i for i in range(seg_start,st-2,3) if s[i:i+3]=='ATG']
                prot_len=(st-seg_start)//3
                out.append([out_prot for out_prot in []] ) if False else None
                out2=(prot_len, seg_start+1, st+3, len(starts))
                out.append(out2)
            prev=st
        # after last stop
        seg_start=prev+3
        if len(s)-2>= seg_start:
            pass  # uncertain (no stop) skip
    return out
for tag,s in (('+',seq),('-',rc(seq))):
    o=all_orfs(s,30)
    print('=== strand',tag,'closed ORFs>=30aa (len_aa, nt_start1b, nt_stop_end1b, n_ATG-in-ORF):')
    for x in sorted(o,key=lambda t:-t[0])[:15]:
        print('   ',x)
    print('   total closed ORFs >=30aa:',len(o))
